/*
 * Parity check for the Qwen4-Exp CUDA expert dequantisers, run on the host.
 *
 * bodies.inc is generated by tests/qwen4exp_cuda_moe_parity.sh, which lifts
 * the Q5_K and Q6_K accessors and the two block structs straight out of
 * ds4_cuda_qwen4exp.cu.  With __device__ and __forceinline__ defined away the
 * bodies are ordinary C99, so the host can run the exact code the GPU runs and
 * compare it with the double-precision reference from ggml-quants.c.
 *
 * This exists because the Metal expert GEMM has tests/test_qwen4exp_moe and the
 * CUDA one has nothing that runs without a CUDA host.  It checks the element
 * decode only; the GEMM around it is identical to the Metal twin line for line.
 */

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define __device__
#define __forceinline__
#define CUDA_QK_K 256

/* ds4_cuda_qwen4exp.cu reaches float through __half2float.  IEEE half to float
 * is exact and has one answer, so the host conversion below is the same
 * function; it is not an approximation of the device one. */
static float dev_f16_to_f32(uint16_t h) {
    const uint32_t sign = (uint32_t)(h & 0x8000u) << 16;
    const uint32_t exp = (h >> 10) & 0x1fu;
    const uint32_t man = h & 0x3ffu;
    union { uint32_t u; float f; } bits;
    if (exp == 0) {
        if (man == 0) { bits.u = sign; return bits.f; }
        union { uint32_t u; float f; } base;
        bits.u = sign | 0x38800000u | (man << 13);
        base.u = sign | 0x38800000u;
        return bits.f - base.f;
    }
    if (exp == 31) { bits.u = sign | 0x7f800000u | (man << 13); return bits.f; }
    bits.u = sign | ((exp + 112u) << 23) | (man << 13);
    return bits.f;
}

#include "bodies.inc"

/* ---------------------------------------------------------------- */
/* The reference, from ggml-quants.c.  Same shape as the one in
 * tests/test_qwen4exp_moe.c, written against the byte layout rather than
 * against a struct, so it shares no code with the extracted bodies. */

static void ref_scale_min(const uint8_t *q, int j, int *sc, int *m) {
    if (j < 4) {
        *sc = q[j] & 63;
        *m = q[j + 4] & 63;
    } else {
        *sc = (q[j + 4] & 0x0f) | ((q[j - 4] >> 6) << 4);
        *m = (q[j + 4] >> 4) | ((q[j] >> 6) << 4);
    }
}

static double ref_q5_K_value(const uint8_t *block, uint32_t k) {
    const uint8_t *xb = block + (k / 256u) * 176u;
    const uint32_t idx = k % 256u;
    const uint32_t group = idx / 32u;
    const uint32_t l = idx % 32u;
    const float d = dev_f16_to_f32((uint16_t)(xb[0] | ((uint16_t)xb[1] << 8)));
    const float dmin = dev_f16_to_f32((uint16_t)(xb[2] | ((uint16_t)xb[3] << 8)));
    const uint8_t *qh = xb + 16;
    const uint8_t *qs = xb + 48;
    int sc = 0, m = 0;
    ref_scale_min(xb + 4, (int)group, &sc, &m);
    const uint8_t byte = qs[(group >> 1) * 32u + l];
    uint32_t q = (group & 1u) ? (uint32_t)(byte >> 4) : (uint32_t)(byte & 0x0fu);
    if (qh[l] & (uint8_t)(1u << group)) q += 16u;
    return (double)d * (double)sc * (double)q - (double)dmin * (double)m;
}

static double ref_q6_K_value(const uint8_t *block, uint32_t k) {
    const uint8_t *xb = block + (k / 256u) * 210u;
    const uint32_t idx = k % 256u;
    const uint32_t n128 = idx >> 7;
    const uint32_t r = idx & 127u;
    const uint32_t l = r & 31u;
    const uint32_t quarter = r >> 5;
    const uint8_t *ql = xb + n128 * 64u;
    const uint8_t *qh = xb + 128 + n128 * 32u;
    const int8_t *scales = (const int8_t *)(xb + 192) + n128 * 8u;
    const float d = dev_f16_to_f32((uint16_t)(xb[208] | ((uint16_t)xb[209] << 8)));
    const uint32_t hi = ((uint32_t)qh[l] >> (quarter * 2u)) & 3u;
    const uint32_t lo = (quarter & 1u) ? (uint32_t)ql[32u + l] : (uint32_t)ql[l];
    const uint32_t q = (quarter < 2u) ? ((lo & 0x0fu) | (hi << 4))
                                      : ((lo >> 4) | (hi << 4));
    const int sc = scales[l / 16u + quarter * 2u];
    return (double)d * (double)sc * (double)((int32_t)q - 32);
}

/* ---------------------------------------------------------------- */

static uint64_t rng_state = 0x243f6a8885a308d3ull;

static uint32_t rng_u32(void) {
    rng_state = rng_state * 6364136223846793005ull + 1442695040888963407ull;
    return (uint32_t)(rng_state >> 32);
}

/* A half that is an exact power of two in [2^-10, 2^-6], so the comparison
 * below can demand bit equality.
 *
 * The extracted accessors return float and the reference works in double.  For
 * a general scale those two round differently in the last bits and equality
 * would have to become a tolerance, which no longer proves the decode is
 * exact.  With a power-of-two scale every product stays exact in both: Q5_K
 * reaches sc*q <= 1953 and m <= 63, and with the two exponents within four of
 * each other the difference needs 15 bits; Q6_K reaches |sc*(q-32)| <= 4096,
 * 13 bits.  Both fit float's 24.  Nothing that carries the layout is
 * constrained: the packed nibbles, the high-bit planes, the packed six-bit
 * scale/min pairs and the int8 scales stay fully random. */
static uint16_t rng_half_scale(void) {
    const uint32_t sign = (rng_u32() & 1u) << 15;
    const uint32_t exp = 5u + (rng_u32() % 5u);
    return (uint16_t)(sign | (exp << 10));
}

enum { SUPERBLOCKS = 3, TRIALS = 200 };

int main(void) {
    uint8_t b5[176 * SUPERBLOCKS];
    uint8_t b6[210 * SUPERBLOCKS];
    int mismatches = 0;

    for (int trial = 0; trial < TRIALS; trial++) {
        for (size_t i = 0; i < sizeof(b5); i++) b5[i] = (uint8_t)rng_u32();
        for (size_t i = 0; i < sizeof(b6); i++) b6[i] = (uint8_t)rng_u32();
        /* Only the f16 scales are constrained, so the packed payload, the
         * six-bit scale/min pairs and the int8 scales stay fully random. */
        for (int b = 0; b < SUPERBLOCKS; b++) {
            const uint16_t d5 = rng_half_scale();
            const uint16_t m5 = rng_half_scale();
            const uint16_t d6 = rng_half_scale();
            b5[b * 176 + 0] = (uint8_t)(d5 & 0xff);
            b5[b * 176 + 1] = (uint8_t)(d5 >> 8);
            b5[b * 176 + 2] = (uint8_t)(m5 & 0xff);
            b5[b * 176 + 3] = (uint8_t)(m5 >> 8);
            b6[b * 210 + 208] = (uint8_t)(d6 & 0xff);
            b6[b * 210 + 209] = (uint8_t)(d6 >> 8);
        }
        for (uint32_t k = 0; k < 256u * SUPERBLOCKS; k++) {
            const double cuda5 = dev_qwen4exp_q5_K_value((const char *)b5, k);
            const double ref5 = ref_q5_K_value(b5, k);
            if (cuda5 != ref5) {
                if (mismatches++ < 5) {
                    printf("q5_K element %u: CUDA %.9g, reference %.9g\n",
                           k, cuda5, ref5);
                }
            }
            const double cuda6 = dev_qwen4exp_q6_K_value((const char *)b6, k);
            const double ref6 = ref_q6_K_value(b6, k);
            if (cuda6 != ref6) {
                if (mismatches++ < 5) {
                    printf("q6_K element %u: CUDA %.9g, reference %.9g\n",
                           k, cuda6, ref6);
                }
            }
        }
    }

    if (mismatches != 0) {
        printf("qwen4exp CUDA MoE parity: %d mismatches\n", mismatches);
        return 1;
    }
    printf("qwen4exp CUDA MoE parity: PASS "
           "(%d rows x %d elements, Q5_K and Q6_K, exact)\n",
           TRIALS, 256 * SUPERBLOCKS);
    return 0;
}
